    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Start from n//2 and go downwards to find the largest divisor
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i
    return 1

