def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors of a
    factors = []
    temp = a

    # Check for factor 2
    while temp % 2 == 0:
        factors.append(2)
        temp //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= temp:
        while temp % i == 0:
            factors.append(i)
            temp //= i
        i += 2

    # If temp is still greater than 1, then it's a prime factor
    if temp > 1:
        factors.append(temp)

    # Check if we have exactly 3 prime factors (with multiplicity)
    return len(factors) == 3 and all(is_prime(f) for f in factors)

