def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the format is mm-dd-yyyy (using hyphens)
    if '-' not in date:
        return False

    # Split the date string by hyphens
    parts = date.split('-')

    # Must have exactly 3 parts
    if len(parts) != 3:
        return False

    # Extract month, day, and year
    month_str = parts[0]
    day_str = parts[1]
    year_str = parts[2]

    # Check if all parts are digits
    if not (month_str.isdigit() and day_str.isdigit() and year_str.isdigit()):
        return False

    # Convert to integers
    try:
        month = int(month_str)
        day = int(day_str)
        year = int(year_str)
    except ValueError:
        return False

    # Check if month is between 1 and 12
    if month < 1 or month > 12:
        return False

    # Check if day is valid based on month
    if month in [1, 3, 5, 7, 8, 10, 12]:  # 31 days
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:  # 30 days
        if day < 1 or day > 30:
            return False
    elif month == 2:  # February - 29 days (leap year check)
        if day < 1 or day > 29:
            return False

    # Additional check for February 29 in leap years
    if month == 2 and day == 29:
        # Check if it's a leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            # Leap year - valid
            pass
        else:
            # Not a leap year - invalid
            return False

    return True

