    has_letter = False
    result = []

    # Check each character and determine if it's a letter
    for char in s:
        if char.isalpha():
            has_letter = True
            # Reverse the case of letters
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    # If no letters were found, reverse the entire string
    if not has_letter:
        return s[::-1]

    return ''.join(result)

